<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Site_General_Model extends CI_Model
{

	public function countotpentry($mobile = '')
	{

		$query = $this->db->select('count(id) as totalid')
			->where('rec_date', date('Y-m-d'))
			->where('mobile', $mobile)
			->get('otpverification')
			->row();


		return $query->totalid;
	}

	public function countlastusersms($mobile)
	{

		$query = $this->db->select('id, update_date')
			->where('mobile', $mobile)
			->get('user_registration')
			->row();


		return $query;
	}

	public function generateotp($mobile = NULL, $email = NULL, $provider = 1)
	{

		$otpcode = rand(1000, 9999);

		$data = array(
			'rec_date' => date('Y-m-d'),
			'mobile' => $mobile,
			'email' => $email,
			'otpcode' => $otpcode
		);
		$id = $this->db->insert('otpverification', $data);

		$message = "Hello, ".$otpcode." is your indiafinpro OTP to register your mobile number. Do not share it with anyone.";
		
		$smsresponse = sendotpSMSobb($mobile, $message);


		return $id;
	}

	public function checkotp($fieldvalue = NULL, $otpcode = NULL)
	{

		$where = " (mobile=" . $fieldvalue . " OR email=" . $fieldvalue . " ) ";

		$lastotp = $this->db->select('otpcode')
			->where('rec_date', date('Y-m-d'))
			->where($where)
			->order_by('id desc')
			->limit(1)
			->get('otpverification')
			->row();


		if ($lastotp->otpcode == $otpcode) {
			return true;
		} else {
			return false;
		}
	}

	public function single_file_upload($my_file, $file_path, $types = "*", $flaque = 1)
	{
		$this->load->library('upload');

		$config = array(
			'allowed_types' => $types,  //'gif|jpg|jpeg|png|iso|dmg|zip|rar|doc|docx|xls|xlsx|ppt|pptx|csv|ods|odt|odp|pdf|rtf|sxc|sxi|txt|exe|avi|mpeg|mp3|mp4|3gp',
			'upload_path' => './assets/' . $file_path,
			'overwrite' => FALSE,
			'max_size' => 20000,
			'encrypt_name' => TRUE
		);

		$this->upload->initialize($config);

		if ($this->upload->do_upload($my_file)) {
			$image_data = $this->upload->data();
		} else {
			$error = $this->upload->display_errors();
			return false;
		}

		if ($flaque == 1) {
			$config = array(
				'source_image' => $image_data['full_path'],
				'new_image' => './uploads/' . $file_path . '/thumbs',
				'maintain_ration' => TRUE,
				'width' => 150
			);

			$this->load->library('image_lib', $config);
			$this->image_lib->resize();
		}

		return $image_data['file_name'];
	}

	public function filedownload($file_path, $file_name)
	{
		//load download helper
		$this->load->helper('download');

		//file path
		$file = './assets/' . $file_path . '/' . $file_name;

		//download file from directory
		force_download($file, NULL);
	}

